export type Store<T extends object> = Prettify<
  {
    readonly [K in keyof T as `get${Capitalize<K & string>}`]: () => T[K];
  } & {
    readonly [K in keyof T as `set${Capitalize<K & string>}`]: (value: T[K]) => void;
  } & {
    readonly snapshot: () => Readonly<T>;
  }
>;

const capitalize = (key: string): string => key.charAt(0).toUpperCase() + key.slice(1);

export function createStore<T extends object>(initial: T): Store<T> {
  const state: T = { ...initial };
  const api: Record<string, unknown> = {
    snapshot: (): Readonly<T> => ({ ...state }),
  };
  for (const key of Object.keys(state) as (keyof T & string)[]) {
    api[`get${capitalize(key)}`] = (): T[typeof key] => state[key];
    api[`set${capitalize(key)}`] = (value: unknown): void => {
      state[key] = value as T[typeof key];
    };
  }
  return api as Store<T>;
}

