references.solution.ts:
// v3ta03_template_literal_types / challenge - reference solution (author only).

export type EventMap = {
  "user:created": { id: string };
  "user:deleted": { id: string; reason: string };
  "app:ready": { at: number };
};

export type EventName = keyof EventMap & string;

export type Namespace = EventName extends `${infer NS}:${string}` ? NS : never;

export type EventsIn<NS extends Namespace> = Extract<EventName, `${NS}:${string}`>;

type Listener = (name: string, payload: never) => void;

export class Emitter {
  private readonly listeners = new Map<string, Set<Listener>>();

  on<K extends EventName>(name: K, handler: (payload: EventMap[K]) => void): () => void {
    return this.subscribe(name, (_name, payload) => {
      (handler as (p: unknown) => void)(payload);
    });
  }

  onNamespace<NS extends Namespace>(
    namespace: NS,
    handler: <K extends EventsIn<NS>>(name: K, payload: EventMap[K]) => void,
  ): () => void {
    return this.subscribe(`${namespace}:*`, handler as Listener);
  }

  emit<K extends EventName>(name: K, payload: EventMap[K]): void {
    const namespace = name.slice(0, name.indexOf(":"));
    for (const key of [name, `${namespace}:*`]) {
      for (const listener of this.listeners.get(key) ?? []) {
        (listener as (n: string, p: unknown) => void)(name, payload);
      }
    }
  }

  private subscribe(key: string, listener: Listener): () => void {
    const set = this.listeners.get(key) ?? new Set<Listener>();
    set.add(listener);
    this.listeners.set(key, set);
    return () => {
      set.delete(listener);
    };
  }
}

// v3ta03_template_literal_types / review1 - reference solution (author only).

export type VarsOf<S extends string> = S extends `${string}{{${infer Var}}}${infer Rest}`
  ? Var | VarsOf<Rest>
  : never;

export type Context<S extends string> = { [K in VarsOf<S>]: string };

export function render<S extends string>(template: S, context: Context<S>): string {
  return template.replace(/{{(\w+)}}/g, (_match, key: string) =>
    Object.prototype.hasOwnProperty.call(context, key)
      ? String((context as Record<string, string>)[key])
      : "",
  );
}

