// v3ta04_recursive_types_depth / challenge - reference solution (author only).

export type DeepGet<T, P extends string> = P extends `${infer Key}.${infer Rest}`
  ? Key extends keyof T
    ? DeepGet<T[Key], Rest>
    : undefined
  : P extends keyof T
    ? T[P]
    : undefined;

export function getIn<T extends object, P extends string>(source: T, path: P): DeepGet<T, P> {
  let current: unknown = source;
  for (const key of path.split(".")) {
    if (current === null || typeof current !== "object" || !(key in current)) {
      return undefined as DeepGet<T, P>;
    }
    current = (current as Record<string, unknown>)[key];
  }
  return current as DeepGet<T, P>;
}

// v3ta04_recursive_types_depth / review1 - reference solution (author only).

export type Tree<T> = { value: T; children: readonly Tree<T>[] };

export type Leaves<T> = T extends { value: infer V; children: readonly [] }
  ? V
  : T extends { children: readonly (infer C)[] }
    ? Leaves<C>
    : never;

export type Depth<T, Acc extends unknown[] = []> = T extends {
  children: readonly (infer C)[];
}
  ? [C] extends [never]
    ? [...Acc, unknown]["length"]
    : Depth<C, [...Acc, unknown]>
  : Acc["length"];

export function collect<T>(tree: Tree<T>): T[] {
  return [tree.value, ...tree.children.flatMap(collect)];
}
